function header(active=''){return `${PROD?'':'<div class="preview-strip"><div class="container"><span><span class="status-dot"></span>Aperçu privé</span><span>Maquette du nouveau site GP Finances</span></div></div>'}<header class="site-header" id="header"><div class="container header-inner">${brand}<nav class="desktop-nav" aria-label="Navigation principale">${services.map(s=>`<a ${active===s.slug?'aria-current="page"':''} href="${s.slug}.html">${s.short}</a>`).join('')}<a href="${CONSEILS_HREF}">Conseils</a></nav><div class="header-actions"><a class="header-phone" href="tel:+33651224213">06 51 22 42 13</a>${rdv}</div><button class="menu-toggle" aria-expanded="false" aria-controls="mobile-nav" aria-label="Ouvrir le menu">${icon('menu')}</button></div><nav class="services-strip" aria-label="Nos services"><div class="container">${services.map(s=>`<a ${active===s.slug?'aria-current="page"':''} href="${s.slug}.html">${s.short}</a>`).join('')}<a href="${CONSEILS_HREF}">Conseils</a></div></nav><nav id="mobile-nav" class="mobile-nav" aria-label="Navigation mobile" hidden>${services.map(s=>`<a ${active===s.slug?'aria-current="page"':''} href="${s.slug}.html">${s.name}${icon('arrow')}</a>`).join('')}<a href="${CONSEILS_HREF}">Conseils${icon('arrow')}</a>${rdv}</nav></header>`;}
function stats(){return `<section class="stats-section" aria-labelledby="stats-title"><div class="container">${label('La confiance, en chiffres')}<h2 id="stats-title">Des résultats qui parlent.</h2><div class="stats-grid"><div><p class="stat-number"><span data-stat="savings" data-live-savings>${data.savings}</span><span class="euro"> €</span></p><p>économisés par nos clients<br>en assurance emprunteur</p></div><div><p class="stat-number" data-stat="partners">${data.partners}</p><p>assureurs partenaires<br>pour comparer les solutions</p></div><div><p class="stat-number"><span data-stat="managed">${data.managed}</span><span class="percent"> %</span></p><p>des démarches<br>prises en charge</p></div></div></div></section>`;}
function process(){return `<section class="section process-section" id="methode"><div class="container">${label('Notre méthode')}<div class="section-heading"><h2>Je m’occupe de tout.</h2><p>Vous choisissez la solution. Je gère le reste.</p></div><div class="process-grid">${[['J’analyse','Votre situation, vos objectifs et vos contrats actuels.'],['Je compare','Les solutions du marché pour trouver celles qui vous correspondent.'],['Je gère','Les démarches, de l’étude jusqu’à la mise en place.']].map(([title,text],i)=>`<article class="process-step"><div class="step-top"><span class="step-number">0${i+1}</span><span class="step-line"></span></div><h3>${title}</h3><p>${text}</p></article>`).join('')}</div></div></section>`;}
function comparison(type='assurance',tabs=false){return `<section class="section comparison-section" id="cas-concret"><div class="container comparison-layout"><div>${label('Avant / Après')}<h2>Moins de promesses.<br>Plus de concret.</h2><p class="section-intro">Des chiffres clairs pour mesurer l’intérêt d’une solution.</p>${tabs?'<div class="comparison-tabs" role="tablist" aria-label="Choisir un exemple"><button role="tab" aria-selected="true" data-comparison="assurance">Assurance emprunteur</button><button role="tab" aria-selected="false" data-comparison="per">PER</button></div>':''}<button class="text-link" data-book>Et dans ma situation ? ${icon('arrow')}</button></div><div class="comparison-card" data-comparison-card="${type}"></div></div></section>`;}
function testimonials(kind='mixed'){const allRows=kind==='per'?[['temoignage-dorothee.png','Dorothée','Plan Épargne Retraite','PER/temoignage-1-dorothee.mp4'],['temoignage-anaelle.png','Anaëlle','Plan Épargne Retraite','PER/temoignage-2-anaelle.mp4']]:[['temoignage-assurance.png','21 200 € économisés','Assurance emprunteur','Tem1.mp4'],['temoignage-dorothee.png','Dorothée','Plan Épargne Retraite','PER/temoignage-1-dorothee.mp4'],['temoignage-anaelle.png','Anaëlle','Plan Épargne Retraite','PER/temoignage-2-anaelle.mp4']];const rows=kind==='per'?allRows.reverse():kind==='assurance'?[allRows[0],['temoignage-dorothee-assurance.png','Dorothée','Assurance emprunteur · 17 000 € économisés','Tem2.mp4'],['temoignage-djian.png','Johanna','Assurance emprunteur · 14 100 € économisés','Tem4.mp4'],['temoignage-9000.png','John','Assurance emprunteur · 9 000 € économisés','Tem5.mp4'],['temoignage-paul.png','Paul','Assurance emprunteur · 12 000 € économisés','Tem6.mp4']]:allRows;const cards=rows.map(([img,name,subject,video])=>`<li class="proof-card proof-story"><button type="button" data-video="https://gp-finances.fr/videos/${video}" data-video-title="Témoignage — ${name}" aria-label="Lire le témoignage : ${name}"><span class="proof-story-photo"><img src="assets/${img}" alt="" loading="lazy" width="320" height="210"><span class="proof-story-play">${icon('play')}<span>Voir son témoignage</span></span></span><span class="proof-story-copy">${kind==='per'?'':`<span class="small-caps">${subject}</span>`}<strong>${name}</strong></span></button></li>`).join('');return `<section class="section testimonials-section" id="temoignages" data-review-carousel><div class="container"><div class="section-heading heading-row"><div>${label('Ils nous font confiance')}<h2>Leurs mots, leur expérience.</h2></div><p>Découvrez les témoignages<br>de nos clients, en vidéo.</p></div><div class="review-toolbar" hidden><button type="button" class="review-auto" data-review-toggle aria-pressed="false">${icon('play')}<span>Mettre en pause</span></button><div class="review-navigation"><span class="review-position" aria-live="off"></span><button type="button" class="review-arrow" data-review-prev aria-label="Témoignage précédent">←</button><button type="button" class="review-arrow" data-review-next aria-label="Témoignage suivant">→</button></div></div><div class="review-viewport" tabindex="0" role="region" aria-label="Témoignages vidéo — faire défiler"><ul class="review-track">${cards}</ul></div></div></section>`;}
function advisor(){return `<section class="section advisor-section" id="votre-courtier"><div class="container advisor-layout"><div class="advisor-photo"><img src="assets/gabriel-perbost.jpeg" alt="Gabriel Perbost dans son bureau" loading="lazy"><span class="photo-frame"></span></div><div class="advisor-copy">${label('Votre courtier')}<h2>Gabriel Perbost</h2><p class="advisor-role">Courtier indépendant</p><p class="section-intro">Un interlocuteur unique pour analyser votre situation, comparer les solutions et gérer vos démarches.</p><p class="advisor-note">Une relation directe. Des explications claires.<br>Un accompagnement à chaque étape.</p>${rdv}<p class="registration">GP FINANCES · ORIAS 23003789</p></div></div></section>`;}
